kLen = input(7, "K Neighbors", 1, 15, 1)
lookback = input(20, "Feature Lookback", 10, 60, 1)
featLen = input(5, "Feature Vector Length", 2, 10, 1)
marginThresh = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
disagThresh = input(0.35, "Disagreement Threshold", 0.05, 1.0, 0.01)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Returns: r[i] = (close[i] - close[i-1]) / close[i-1] ───
c0 = close
c1 = close[1]
c2 = close[2]
c3 = close[3]
c4 = close[4]
c5 = close[5]
e = 0.000000001
r0 = (c0 - c1) / (c1 + e)
r1 = (c1 - c2) / (c2 + e)
r2 = (c2 - c3) / (c3 + e)
r3 = (c3 - c4) / (c4 + e)
r4 = (c4 - c5) / (c5 + e)

// ─── KNN vote over last 20 bars, Euclidean distance on 5 returns ───
bD1 = 1000000000.0
bD2 = 1000000000.0
bD3 = 1000000000.0
bD4 = 1000000000.0
bD5 = 1000000000.0
bD6 = 1000000000.0
bD7 = 1000000000.0
bL1 = 0
bL2 = 0
bL3 = 0
bL4 = 0
bL5 = 0
bL6 = 0
bL7 = 0

ready = bar_index > (lookback + 6)

j = 1
while j <= lookback {
    fj0 = (close[j] - close[j + 1]) / (close[j + 1] + e)
    fj1 = (close[j + 1] - close[j + 2]) / (close[j + 2] + e)
    fj2 = (close[j + 2] - close[j + 3]) / (close[j + 3] + e)
    fj3 = (close[j + 3] - close[j + 4]) / (close[j + 4] + e)
    fj4 = (close[j + 4] - close[j + 5]) / (close[j + 5] + e)
    d0 = (r0 - fj0) * (r0 - fj0)
    d1 = (r1 - fj1) * (r1 - fj1)
    d2 = (r2 - fj2) * (r2 - fj2)
    d3 = (r3 - fj3) * (r3 - fj3)
    d4 = (r4 - fj4) * (r4 - fj4)
    sumSq = d0
    if featLen >= 2 { sumSq := sumSq + d1 }
    if featLen >= 3 { sumSq := sumSq + d2 }
    if featLen >= 4 { sumSq := sumSq + d3 }
    if featLen >= 5 { sumSq := sumSq + d4 }
    dist = sqrt(sumSq)
    lj = 0 - 1
    if close[j - 1] > close[j] { lj := 1 }
    if dist < bD1 {
        bD7 := bD6
        bL7 := bL6
        bD6 := bD5
        bL6 := bL5
        bD5 := bD4
        bL5 := bL4
        bD4 := bD3
        bL4 := bL3
        bD3 := bD2
        bL3 := bL2
        bD2 := bD1
        bL2 := bL1
        bD1 := dist
        bL1 := lj
    } else {
        if dist < bD2 {
            bD7 := bD6
            bL7 := bL6
            bD6 := bD5
            bL6 := bL5
            bD5 := bD4
            bL5 := bL4
            bD4 := bD3
            bL4 := bL3
            bD3 := bD2
            bL3 := bL2
            bD2 := dist
            bL2 := lj
        } else {
            if dist < bD3 {
                bD7 := bD6
                bL7 := bL6
                bD6 := bD5
                bL6 := bL5
                bD5 := bD4
                bL5 := bL4
                bD4 := bD3
                bL4 := bL3
                bD3 := dist
                bL3 := lj
            } else {
                if dist < bD4 {
                    bD7 := bD6
                    bL7 := bL6
                    bD6 := bD5
                    bL6 := bL5
                    bD5 := bD4
                    bL5 := bL4
                    bD4 := dist
                    bL4 := lj
                } else {
                    if dist < bD5 {
                        bD7 := bD6
                        bL7 := bL6
                        bD6 := bD5
                        bL6 := bL5
                        bD5 := dist
                        bL5 := lj
                    } else {
                        if dist < bD6 {
                            bD7 := bD6
                            bL7 := bL6
                            bD6 := dist
                            bL6 := lj
                        } else {
                            if dist < bD7 {
                                bD7 := dist
                                bL7 := lj
                            }
                        }
                    }
                }
            }
        }
    }
    j := j + 1
}

