rows = input(24, "Rows", 10, 48, 1)
vaPct = input(70, "ValueAreaPercent", 50, 90, 5)
lookback = input(120, "SessionLookbackBars", 30, 300, 10)
show3D = input(true, "Show3D")
terrainScale = input(1.0, "TerrainHeightScale", 0.2, 3.0, 0.1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session window range (Wilder-style range, validated session high/low) ──
sessHigh = highest(high, lookback)
sessLow = lowest(low, lookback)
rng = sessHigh - sessLow
if rng <= 0 { rng := close * 0.01 }
binSize = rng / rows

// ─── Volume-at-price bins with overlap apportion ─────────────────────
binVol = array()
k = 0
while k < rows {
    array.push(binVol, 0.0)
    k := k + 1
}

totalVol = 0.0
j = 0
while j < lookback {
    hb = high[j]
    lb = low[j]
    vb = volume[j]
    totalVol := totalVol + vb
    barRng = hb - lb
    b = 0
    while b < rows {
        binLo = sessLow + b * binSize
        binHi = binLo + binSize
        share = 0.0
        if barRng <= 0 {
            mid = sessLow + (b + 0.5) * binSize
            if close[j] >= binLo and close[j] < binHi { share := 1.0 }
            if b == rows - 1 and close[j] == sessHigh { share := 1.0 }
        } else {
            ovTop = hb
            if binHi < ovTop { ovTop := binHi }
            ovBot = lb
            if binLo > ovBot { ovBot := binLo }
            ov = ovTop - ovBot
            if ov > 0 { share := ov / barRng }
        }
        if share > 0 {
            array.set(binVol, b, array.get(binVol, b) + vb * share)
        }
        b := b + 1
    }
    j := j + 1
}

// ─── POC = bin with max volume ───────────────────────────────────────
pocBin = 0
maxVol = array.get(binVol, 0)
b = 1
while b < rows {
    v = array.get(binVol, b)
    if v > maxVol {
        maxVol := v
        pocBin := b
    }
    b := b + 1
}
pocPrice = sessLow + (pocBin + 0.5) * binSize

// ─── Value area: sort-by-volume-descending accumulation ──────────────
picked = array()
b = 0
while b < rows {
    array.push(picked, 0.0)
    b := b + 1
}
target = totalVol * vaPct / 100
accum = 0.0
vaMinBin = pocBin
vaMaxBin = pocBin
guard = 0
while accum < target and guard < rows {
    bestIdx = 0 - 1
    bestVal = 0 - 1.0
    b := 0
    while b < rows {
        if array.get(picked, b) == 0 {
            v = array.get(binVol, b)
            if v > bestVal {
                bestVal := v
                bestIdx := b
            }
        }
        b := b + 1
    }
    if bestIdx < 0 { guard := rows }
    if bestIdx >= 0 {
        array.set(picked, bestIdx, 1.0)
        accum := accum + bestVal
        if bestIdx < vaMinBin { vaMinBin := bestIdx }
        if bestIdx > vaMaxBin { vaMaxBin := bestIdx }
    }
    guard := guard + 1
}
vahPrice = sessLow + (vaMaxBin + 1) * binSize
valPrice = sessLow + vaMinBin * binSize

// ─── Terrain height: value width at close price (price-denominated) ──
closeBin = floor((close - sessLow) / rng * rows)
if closeBin < 0 { closeBin := 0 }
if closeBin > rows - 1 { closeBin := rows - 1 }
closeBinVol = array.get(binVol, closeBin)
normVol = 0.0
if maxVol > 0 { normVol := closeBinVol / maxVol }
terrainPrice = pocPrice + normVol * rng * 0.5 * terrainScale
pocElev = pocPrice + 1.0 * rng * 0.02 * terrainScale

// ─── Signals: price leaving value, edge only ─────────────────────────
prevClose = close[1]
wasInside = prevClose >= valPrice[1] and prevClose <= vahPrice[1]
buySig = wasInside and close > vahPrice
sellSig = wasInside and close < valPrice
if buySig { plotshape(bar_index, low, "Buy", "triangleup", "#22cc88") }
if sellSig { plotshape(bar_index, high, "Sell", "triangledown", "#ff4477") }
if buySig { plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "3d") }
if sellSig { plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 1, "3d") }

// ─── 2D: same information when 3D is off ─────────────────────────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(terrainPrice, "Value Terrain Twin", "#4488ff", 1, "separate")
plot(normVol * 100, "Value Width %", "#4488ff", 1, "separate")

// ─── 3D: value terrain + POC labelled rail + VAH/VAL boundary rails ──
plot3d(terrainPrice, "Value Terrain", "surface", "#4488ff", "3d", 3)
plot3d(pocElev, "POC Rail", "line3d", "#ffd43b", "3d", 0)
plot3d(vahPrice, "VAH Rail", "line3d", "#22cc88", "3d", 1)
label3d(bar_index, pocElev, "POC", "#ffd43b", 1.0, 0, "3d")

