discSpin = spinAngleMod + flowPsi * 0.01
ringExpand = ringOuter + lockedBars * expansionRate
overOffset = flowPsi + 10 + lockedBars * 0.2

lockEdge = isOver and not isOver[1]
clearEdge = not isOver and isOver[1]
